#include <stdio.h>
#include <stdlib.h>

typedef struct { int s, e; } Interval;

int cmp(const void *a, const void *b) {
    return ((Interval*)a)->s - ((Interval*)b)->s;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    Interval *arr = (Interval*)malloc(n * sizeof(Interval));
    for (int i = 0; i < n; i++) {
        scanf("%d %d", &arr[i].s, &arr[i].e);
    }
    qsort(arr, n, sizeof(Interval), cmp);
    int cur_s = arr[0].s, cur_e = arr[0].e;
    for (int i = 1; i < n; i++) {
        if (arr[i].s <= cur_e) {
            if (arr[i].e > cur_e) cur_e = arr[i].e;
        } else {
            printf("%d %d\n", cur_s, cur_e);
            cur_s = arr[i].s;
            cur_e = arr[i].e;
        }
    }
    printf("%d %d\n", cur_s, cur_e);
    free(arr);
    return 0;
}
